        uint256 lidoLockedETH;
        uint256 eigenLayerPendingWithdrawalSharesAmount;
        bool isLidoWithdrawal; // Not in use in PufferVaultV2
        EnumerableSet.UintSet lidoWithdrawals; // Not in use in PufferVaultV2
